        self.pid = pid
        self.next = None

class EmergencyQueue:
    def __init__(self):
        self.head = None
        self.tail = None

    def enqueue(self, pid):
        new_node = PatientNode(pid)
        if self.tail is None:
            self.head = self.tail = new_node
        else:
            self.tail.next = new_node
            self.tail = new_node

    def dequeue(self):
        if self.head is None:
            return None
        pid = self.head.pid
        self.head = self.head.next
        if self.head is None:
            self.tail = None
        return pid

    def remove_by_id(self, pid):
        if self.head is None:
            return
        if self.head.pid == pid:
            self.head = self.head.next
            if self.head is None:
                self.tail = None
            return
        current = self.head
        while current.next is not None and current.next.pid != pid:
            current = current.next
        if current.next is not None:
            current.next = current.next.next
            if current.next is None:
                self.tail = current

    def display(self):
        current = self.head
        result = []
        while current is not None:
            result.append(str(current.pid))
            current = current.next
        return ' -> '.join(result) if result else 'Empty'

